<template><div class="page"><div class="head"><h2>巡检任务</h2><p>扫码识别设备后，按关联表单完成巡检，填写内容会自动保存在本机。</p></div><div class="filters"><el-select v-model="query.status" clearable placeholder="全部状态" @change="load"><el-option v-for="(v,k) in statusMap" :key="k" :label="v" :value="k"/></el-select><el-input v-model="query.keyword" clearable placeholder="任务号、设备名称或编号" @keyup.enter="load"/><el-button type="primary" @click="load">查询</el-button></div><div class="cards"><div v-for="x in rows" :key="x.id" class="task-card"><div class="card-top"><b>{{x.targetName}}</b><el-tag :type="tagType(x.status)">{{statusMap[x.status]||x.status}}</el-tag></div><div class="meta">{{x.inspectionTypeName}} · {{x.planName}}</div><div class="meta">计划：{{fmt(x.scheduledAt)}}　截止：{{fmt(x.dueAt)}}</div><div class="meta">负责人：{{x.assigneeName||'未指定'}}　设备：{{x.targetCode||'-'}}</div><div class="actions"><el-button plain @click="showQr(x)">任务二维码</el-button><el-button type="primary" plain @click="open(x)">{{['COMPLETED','CLOSED'].includes(x.status)?'查看结果':'开始巡检'}}</el-button></div></div><el-empty v-if="!rows.length" description="暂无巡检任务"/></div>
<el-drawer v-model="visible" :title="current?.targetName||'巡检任务'" size="min(720px,100%)" destroy-on-close><div v-if="current" class="form"><div class="equipment-title">本次巡检设备资料</div><el-descriptions :column="1" border><el-descriptions-item label="任务编号">{{current.taskNo}}</el-descriptions-item><el-descriptions-item label="设备编号">{{snapshot.equipmentCode||current.targetCode||'-'}}</el-descriptions-item><el-descriptions-item label="设备名称">{{snapshot.equipmentName||current.targetName||'-'}}</el-descriptions-item><el-descriptions-item label="设备分类">{{snapshot.categoryName||'-'}}</el-descriptions-item><el-descriptions-item label="所属系统">{{snapshot.systemName||'-'}}</el-descriptions-item><el-descriptions-item label="安装位置">{{snapshot.installationLocation||current.locationText||'-'}}</el-descriptions-item><el-descriptions-item label="楼层/区域">{{[snapshot.floorCode,snapshot.areaName].filter(Boolean).join(' / ')||'-'}}</el-descriptions-item><el-descriptions-item label="品牌/型号">{{[snapshot.brand,snapshot.model].filter(Boolean).join(' / ')||'-'}}</el-descriptions-item><el-descriptions-item label="规格/出厂编号">{{[snapshot.specification,snapshot.serialNumber].filter(Boolean).join(' / ')||'-'}}</el-descriptions-item><el-descriptions-item label="责任人">{{snapshot.responsiblePerson||'-'}} {{snapshot.responsiblePhone||''}}</el-descriptions-item><el-descriptions-item label="截止时间">{{fmt(current.dueAt)}}</el-descriptions-item></el-descriptions><h3>{{current.templateName}}</h3><div v-for="f in fields" :key="f.key" class="form-item"><div class="label">{{f.label}}<span v-if="f.required"> *</span><small v-if="f.unit">（{{f.unit}}）</small></div><el-radio-group v-if="f.controlType==='RADIO'" v-model="answers[f.key]" @change="saveLocal"><el-radio-button label="正常"/><el-radio-button label="异常"/></el-radio-group><el-input-number v-else-if="f.controlType==='NUMBER'" v-model="answers[f.key]" @change="saveLocal"/><el-select v-else-if="f.controlType==='SELECT'" v-model="answers[f.key]" @change="saveLocal"><el-option v-for="o in f.options||[]" :key="o" :label="o" :value="o"/></el-select><el-upload v-else-if="f.controlType==='PHOTO'" :action="uploadUrl(f.key)" :headers="uploadHeaders" accept="image/jpeg,image/png" list-type="picture-card" :on-success="uploadSuccess"><span>拍照/上传</span></el-upload><el-input v-else v-model="answers[f.key]" type="textarea" @input="saveLocal"/><div v-if="answers[f.key]==='异常'" class="issue-box"><el-input v-model="issueNotes[f.key]" placeholder="请填写异常情况及整改要求" @input="saveLocal"/></div></div><div class="form-item"><div class="label">现场照片</div><el-upload :action="uploadUrl()" :headers="uploadHeaders" accept="image/jpeg,image/png" list-type="picture-card" :on-success="uploadSuccess"><span>拍照/上传</span></el-upload><div class="photo-list"><a v-for="a in attachments" :key="a.id" :href="`/api/v1/inspections/tasks/${current.id}/attachments/${a.id}`" target="_blank">{{a.fileName}}</a></div></div><el-input v-model="summary" type="textarea" placeholder="本次巡检说明" @input="saveLocal"/><div class="draft">{{draftTip}}</div><el-button v-if="!['COMPLETED','CLOSED'].includes(current.status)" type="primary" size="large" class="submit" @click="submit">提交巡检结果</el-button></div></el-drawer><el-dialog v-model="qrVisible" title="巡检任务二维码" width="360"><img v-if="qrTask" class="qr" :src="`/api/v1/inspections/public-qr/${qrTask.accessToken}`"/><p class="qr-tip">扫码后登录即可进入该次巡检任务</p></el-dialog></div></template>
<script setup lang="ts">import{ref,reactive,computed,onMounted}from'vue';import{useRoute}from'vue-router';import{ElMessage}from'element-plus';import{inspectionApi}from'@/api/inspection';const route=useRoute(),token=localStorage.getItem('token')||'',uploadHeaders={Authorization:`Bearer ${token}`};const statusMap:any={PENDING:'待巡检',IN_PROGRESS:'巡检中',COMPLETED:'已完成',PENDING_RECTIFICATION:'待整改',RECTIFIED:'待复核',CLOSED:'已闭环',OVERDUE:'已逾期',CANCELLED:'已取消'};const query=reactive({status:'',keyword:''}),rows=ref<any[]>([]),visible=ref(false),current=ref<any>(),fields=ref<any[]>([]),answers=reactive<any>({}),issueNotes=reactive<any>({}),summary=ref(''),draftTip=ref(''),attachments=ref<any[]>([]),qrVisible=ref(false),qrTask=ref<any>();const unwrap=(r:any)=>r?.data?.data??r?.data??r;const parse=(s:any,d:any)=>{try{return typeof s==='string'?JSON.parse(s):s||d}catch{return d}};const snapshot=computed(()=>parse(current.value?.equipmentSnapshotJson,{}));const fmt=(x:any)=>x?String(x).replace('T',' ').slice(0,19):'-';const tagType=(s:string)=>s==='OVERDUE'?'danger':s==='PENDING_RECTIFICATION'?'warning':['COMPLETED','CLOSED'].includes(s)?'success':'info';const uploadUrl=(photoType='INSPECTION')=>`/api/v1/inspections/tasks/${current.value?.id}/attachments?photoType=${photoType}`;async function load(){rows.value=unwrap(await inspectionApi.tasks(query))}async function open(row:any){current.value=row.accessToken&&!row.id?unwrap(await inspectionApi.taskByToken(row.accessToken)):unwrap(await inspectionApi.task(row.id));fields.value=parse(current.value.fieldsJson,[]);attachments.value=unwrap(await inspectionApi.attachments(current.value.id));Object.keys(answers).forEach(k=>delete answers[k]);Object.keys(issueNotes).forEach(k=>delete issueNotes[k]);Object.assign(answers,parse(current.value.resultJson,{}));const draft=localStorage.getItem(`inspection-draft-${current.value.id}`);if(draft&&!current.value.submittedAt){const d=parse(draft,{});Object.assign(answers,d.answers||{});Object.assign(issueNotes,d.issueNotes||{});summary.value=d.summary||'';draftTip.value='已恢复本机自动保存内容'}visible.value=true}function showQr(x:any){qrTask.value=x;qrVisible.value=true}async function uploadSuccess(r:any){if(r?.code!==0)return ElMessage.error(r?.message||'上传失败');ElMessage.success('照片上传成功');attachments.value=unwrap(await inspectionApi.attachments(current.value.id))}function saveLocal(){if(!current.value)return;localStorage.setItem(`inspection-draft-${current.value.id}`,JSON.stringify({answers:{...answers},issueNotes:{...issueNotes},summary:summary.value,savedAt:new Date()}));draftTip.value='已自动保存 '+new Date().toLocaleTimeString()}async function submit(){for(const f of fields.value)if(f.required&&f.controlType!=='PHOTO'&&(answers[f.key]===undefined||answers[f.key]===''))return ElMessage.warning(`请填写：${f.label}`);const issues=fields.value.filter(f=>answers[f.key]==='异常').map(f=>({fieldKey:f.key,fieldLabel:f.label,level:f.issueLevel||'WARNING',description:issueNotes[f.key]||`${f.label}异常`,rectificationRequirement:issueNotes[f.key]||'请及时核查并整改'}));await inspectionApi.submit(current.value.id,{result:{...answers},summary:summary.value,issues});localStorage.removeItem(`inspection-draft-${current.value.id}`);ElMessage.success(issues.length?'已提交，异常已进入整改':'巡检已完成');visible.value=false;load()}onMounted(async()=>{await load();const taskToken=String(route.query.taskToken||'');if(taskToken)await open({accessToken:taskToken})})
</script>
<style scoped>.page{padding:20px}.head h2{margin:0}.head p,.meta,.draft{color:#777}.filters{display:flex;gap:10px;background:#fff;padding:14px;border-radius:8px;margin:14px 0}.filters .el-input{max-width:360px}.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:12px}.task-card{background:#fff;border-radius:9px;padding:16px;border:1px solid #e8ebef}.card-top{display:flex;justify-content:space-between;gap:8px}.meta{font-size:13px;margin-top:9px}.actions{margin-top:14px;text-align:right}.equipment-title{font-weight:700;margin-bottom:10px}.form-item{padding:15px 0;border-bottom:1px solid #eee}.label{font-weight:600;margin-bottom:9px}.label span{color:#f56c6c}.issue-box{margin-top:8px}.submit{width:100%;margin-top:18px}.draft{font-size:12px;margin-top:8px}.photo-list{display:flex;flex-direction:column;gap:6px;margin-top:8px}.qr{display:block;width:280px;height:280px;margin:auto}.qr-tip{text-align:center;color:#777}@media(max-width:768px){.page{padding:10px}.filters{display:grid}.filters .el-input{max-width:none}.cards{grid-template-columns:1fr}}</style>
